<?php
/* Template Name: AI Learning Pipeline */
if (!is_user_logged_in()) { auth_redirect(); }
get_header();
$nonce = wp_create_nonce('learning_data_action');
$items = get_posts(['post_type' => 'post', 'post_status' => ['pending', 'publish'], 'meta_key' => '_fourier_pipeline_stage', 'posts_per_page' => 30, 'orderby' => 'modified', 'order' => 'DESC']);
?>
<main class="fourier-pipeline" data-ajax="<?php echo esc_url(admin_url('admin-ajax.php')); ?>" data-nonce="<?php echo esc_attr($nonce); ?>">
  <section class="pipeline-hero"><p class="eyebrow">AI LEARNING DATA</p><h1>URLを、レビュー可能な学習データへ。</h1><p>スクレイピングから概念抽出、Knowledge Server登録までを自動で処理します。</p></section>
  <section class="pipeline-card pipeline-input"><label for="pipeline-url">対象URL</label><div class="pipeline-form"><input id="pipeline-url" type="url" placeholder="https://example.com/article" required><select id="pipeline-provider" aria-label="LLMプロバイダ"><option value="openai">OpenAI</option><option value="gemini">Gemini</option><option value="ollama">Ollama</option><option value="custom">Custom</option></select><button id="pipeline-start" type="button">パイプライン開始</button></div><details class="pipeline-settings"><summary>Knowledge Server設定（任意）</summary><div class="pipeline-form pipeline-knowledge"><input id="pipeline-knowledge-url" type="url" placeholder="https://knowledge.example.com"><input id="pipeline-knowledge-token" type="password" placeholder="Bearer token"><small>入力した値はWordPressのユーザーメタに保存されます。</small></div></details><p id="pipeline-feedback" class="pipeline-feedback" role="status"></p></section>
  <section class="pipeline-card concept-input"><div class="eyebrow">CONCEPT DISTILLATION / 概念蒸留 / 概念蒸馏</div><h2>概念から知識を広げる</h2><p class="concept-description">「犬」のような概念を入力すると、観念の枝、枝ごとの質問、複数の回答候補を生成します。<br>Enter a concept to expand its knowledge branches, questions, and answer variants.<br>输入一个概念，自动扩展知识分支、问题和多个回答。</p><label for="pipeline-concept">中心概念 / Root concept / 核心概念</label><div class="pipeline-form"><input id="pipeline-concept" type="text" placeholder="犬 / dog / 狗" maxlength="120"><button id="concept-start" type="button">概念蒸留を開始</button></div><p id="concept-feedback" class="pipeline-feedback" role="status"></p></section>
  <section class="pipeline-card"><div class="pipeline-heading"><div><p class="eyebrow">WORK QUEUE</p><h2>処理キュー</h2></div><span><?php echo count($items); ?> 件</span></div><div id="pipeline-list">
  <?php if (!$items): ?><p class="pipeline-empty">まだ登録されたURLはありません。</p><?php endif; ?>
  <?php foreach ($items as $item): $stage = get_post_meta($item->ID, '_fourier_pipeline_stage', true); $status = get_post_meta($item->ID, '_fourier_pipeline_status', true); $kind = get_post_meta($item->ID, '_fourier_pipeline_kind', true); $source = $kind === 'concept' ? 'Concept: ' . get_post_meta($item->ID, '_fourier_pipeline_concept', true) : ($kind === 'auto_distillation' ? 'Auto Distillation Job #' . get_post_meta($item->ID, '_fourier_auto_job_id', true) : get_post_meta($item->ID, '_fourier_pipeline_url', true)); ?>
    <article class="pipeline-row" data-id="<?php echo (int) $item->ID; ?>"><div><strong><?php echo esc_html($item->post_title); ?></strong><small><?php echo esc_html($source); ?></small></div><div class="pipeline-state"><span class="state-<?php echo esc_attr($status); ?>"><?php echo esc_html($stage); ?></span><small><?php echo esc_html($status); ?></small></div><?php if ($status === 'review'): ?><div class="pipeline-actions"><button class="pipeline-review" data-decision="approve">承認 / Approve / 批准</button><button class="pipeline-review secondary" data-decision="reject">差し戻し / Reject / 驳回</button></div><?php endif; ?></article>
  <?php endforeach; ?></div></section>
  <section class="pipeline-steps"><p class="eyebrow">AUTOMATION FLOW</p><div class="steps-list"><?php foreach (fourier_pipeline_stages() as $i => $stage): ?><div><b><?php echo sprintf('%02d', $i + 1); ?></b><span><?php echo esc_html($stage); ?></span></div><?php endforeach; ?></div><p class="eyebrow concept-flow-label">CONCEPT FLOW</p><div class="steps-list"><?php foreach (fourier_concept_pipeline_stages() as $i => $stage): ?><div><b><?php echo sprintf('%02d', $i + 1); ?></b><span><?php echo esc_html($stage); ?></span></div><?php endforeach; ?></div></section>
</main>
