<script>
(()=>{const root=document.querySelector('.fourier-pipeline');if(!root)return;const ajax=root.dataset.ajax,nonce=root.dataset.nonce,feedback=document.querySelector('#pipeline-feedback');const post=(action,extra={})=>{const f=new FormData();f.append('action',action);f.append('nonce',nonce);Object.entries(extra).forEach(([k,v])=>f.append(k,v));return fetch(ajax,{method:'POST',body:f}).then(r=>r.json())};const knowledge=()=>({provider:document.querySelector('#pipeline-provider').value,knowledge_url:document.querySelector('#pipeline-knowledge-url').value,knowledge_token:document.querySelector('#pipeline-knowledge-token').value});document.querySelector('#pipeline-start').onclick=()=>{const url=document.querySelector('#pipeline-url').value.trim(),b=document.querySelector('#pipeline-start');if(!url){feedback.textContent='URLを入力してください。';return}b.disabled=true;feedback.textContent='キューに追加しています…';post('fourier_pipeline_start',Object.assign({url},knowledge())).then(r=>{feedback.textContent=r.success?'開始しました。数秒後に処理キューを更新します。':(r.data?.message||'開始できませんでした。');if(r.success)setTimeout(()=>location.reload(),1800);b.disabled=false}).catch(()=>{feedback.textContent='通信エラーが発生しました。';b.disabled=false})};document.querySelector('#concept-start').onclick=()=>{const concept=document.querySelector('#pipeline-concept').value.trim(),b=document.querySelector('#concept-start');if(!concept){document.querySelector('#concept-feedback').textContent='概念を入力してください。';return}b.disabled=true;document.querySelector('#concept-feedback').textContent='観念マップをキューに追加しています…';post('fourier_concept_pipeline_start',Object.assign({concept},knowledge())).then(r=>{document.querySelector('#concept-feedback').textContent=r.success?'概念蒸留を開始しました。処理キューを更新します。':(r.data?.message||'開始できませんでした。');if(r.success)setTimeout(()=>location.reload(),1800);b.disabled=false}).catch(()=>{document.querySelector('#concept-feedback').textContent='通信エラーが発生しました。';b.disabled=false})};document.querySelectorAll('.pipeline-review').forEach(b=>b.onclick=()=>{const row=b.closest('.pipeline-row');b.disabled=true;post('fourier_pipeline_review',{post_id:row.dataset.id,decision:b.dataset.decision}).then(r=>{if(r.success)location.reload();else{alert(r.data?.message||'保存できませんでした');b.disabled=false}})})})();
</script>
